import{_ as o,o as i,c as a,a2 as d}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0051 — Migrazione del client desktop a Wails v3 (solo parità)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0051-wails-v3.md","filePath":"adr/0051-wails-v3.md"}'),c={name:"adr/0051-wails-v3.md"};function t(n,e,s,r,l,p){return i(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="adr-0051-—-migrazione-del-client-desktop-a-wails-v3-solo-parita" tabindex="-1">ADR-0051 — Migrazione del client desktop a Wails v3 (solo parità) <a class="header-anchor" href="#adr-0051-—-migrazione-del-client-desktop-a-wails-v3-solo-parita" aria-label="Permalink to &quot;ADR-0051 — Migrazione del client desktop a Wails v3 (solo parità)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata (2026-11-20, decisione dell&#39;owner, opzione A della proposta di spec v1.8); recepita in <code>Specifications.md</code> v1.8 (2026-11-20); spike B-W0 eseguito il 2026-11-10 con esito GO con condizioni; implementata e rilasciata dalla 1.4.0; <strong>la matrice manuale B-W8 su Windows e Linux non è eseguita</strong> (il rischio resta, solo dichiarato); nessun rollback a v2 e criterio di aggiornamento = installazione manuale sopra la 1.3.4, decisi dall&#39;owner il 2026-11-11</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.8 (2026-11-20): V-07, §1.3, A-03, D-07, §2.3.2, §2.5, §4.2 (tre righe), §4.5, C.2 e Appendice C.4 (riga di ADR-0051); <a href="./../spec-v1.8-proposta.html"><code>spec-v1.8-proposta.md</code></a> §6 resta come storia</td></tr><tr><td><strong>Data</strong></td><td>2026-11-10 (proposta); accettata il 2026-11-20</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>V-07, D-07, A-03 (Wails v2); §2.2.1 (pop-out), §2.3.2 (stampa), §4.2, §4.5; V-01 (Wails, invariato); <a href="./0001-url-scheme-delivery.html">ADR-0001</a>, <a href="./0005-webview-csp.html">ADR-0005</a>, <a href="./0023-distribution-and-updates-details.html">ADR-0023</a>, <a href="./0025-desktop-frontend-esbuild.html">ADR-0025</a>, <a href="./0029-web-workbench.html">ADR-0029</a>, <a href="./0030-desktop-core-wasm.html">ADR-0030</a>, <a href="./0031-release-pipeline-unsigned-channel.html">ADR-0031</a>, <a href="./0045-parita-per-costruzione.html">ADR-0045</a></td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì → <strong>recepito in <code>Specifications.md</code> v1.8 (2026-11-20)</strong>; le righe, con i numeri della v1.3 (nello spec v1.8 sono spostati): V-07 (<code>:59</code>), A-03 (<code>:68</code>), D-07 (<code>:1920</code>), §4.5 (<code>:1857</code>, «Wails v2 (versione fissata)»), §4.2 (<code>:1726</code>, <code>platform/</code> «finestra singola, Wails v2»), C.2 (<code>:1944</code>, rischio «Limiti di Wails v2»); da rivedere per coerenza anche <code>:209</code> (single-instance lock di Wails v2), <code>:351</code> (pop-out «Wails v2 gestisce una sola finestra»), <code>:428</code> (stampa in PDF), <code>:489</code> (modulo <code>platform</code>). Restano esclusi pop-out e updater integrato di v3: il perimetro funzionale non cambia</td></tr><tr><td><strong>Superfici</strong></td><td>desktop (shell Wails, <code>CoreBridge</code>, shim <code>wailsHost.ts</code>, build, installer; prove: <code>go test -race</code>, vitest dello shim, smoke scriptato del binario reale, matrice di QA per sistema operativo in <code>docs/qa/</code>) · workbench web (nessun cambiamento funzionale: il core WASM e <code>host_web.go</code> non si toccano; prove: <code>task e2e</code> e la matrice sul core WASM invariate e verdi come prova di non regressione) · console: nessuna · cloud: solo l&#39;immagine (lo stage 1 del Dockerfile smette di usare la CLI Wails, <code>task docker-build</code> verde)</td></tr></tbody></table><blockquote><p><strong>Nota (M23, 2026-11-20).</strong> <a href="./0064-terminale-integrato-e-finestra-separata.html">ADR-0064</a>, <strong>accettata</strong> il 2026-11-20 e recepita in <code>Specifications.md</code> v1.8, emenda il punto «niente pop-out» (la riga «Devia dallo spec?» e il Contesto) <strong>solo per il terminale integrato</strong>: il client ha (M23) una seconda finestra Wails v3, nello stesso processo, che mostra soltanto il terminale. Per ogni altra vista, i pop-out restano esclusi. <strong>Questo ADR è stato accettato il 2026-11-20</strong> (opzione A della proposta di spec v1.8, <a href="./../spec-v1.8-proposta.html"><code>../spec-v1.8-proposta.md</code></a> §0): ADR-0062 e ADR-0064 lo presuppongono. Il testo qui sotto è quello della proposta e <strong>non cambia</strong>: dove dice «in proposta» o «in attesa dell&#39;accettazione» è storia.</p></blockquote><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>La richiesta del 2026-11-10 è passare a Wails v3 mantenendo <strong>tutte</strong> le funzioni esistenti («solo parità»: niente pop-out, niente updater integrato di v3). Lo spec fissa Wails v2 in V-07, D-07 e A-03; il client usava <code>github.com/wailsapp/wails/v2 v2.17.0</code> (<code>apps/desktop/go.mod:19</code> a <code>bd9efc3</code>); B-W2 lo ha portato a 2.17.1 (fix di sicurezza Linux). La roadmap citava ancora v2.12 (corretto in <code>docs/roadmap.md</code>).</p><p>Stato attuale verificato sul repository:</p><ul><li>Wails è importato solo da <code>apps/desktop/main.go:15-19</code> e da <code>apps/desktop/internal/app/host_wails.go:10-11</code>; l&#39;interfaccia <code>Host</code> (<code>internal/app/host.go</code>) e <code>Options.Host</code> (<code>internal/app/app.go:43</code>) esistono già.</li><li>Il frontend usa <code>window.go.app.&lt;Service&gt;.&lt;Method&gt;</code> e <code>window.runtime</code> come ABI. Lo replicano a mano il bridge WASM (<code>web/src/workbench/bridge.ts:455-494</code>), il mock (<code>packages/workbench/src/test/wails-mock</code>) e <code>test/wasmCore.ts</code>; ne dipendono <code>scripts/gen-core-client.mjs</code>, <code>scripts/parity.mjs</code>, <code>internal/app/services_test.go</code> e <code>cloud/bindingTypes.test.ts</code>.</li><li><code>App.Services()</code> (<code>internal/app/services.go:6-29</code>) è l&#39;unico elenco dei servizi (20) ed è servito anche dal dispatcher del core WASM (<code>internal/rpc/rpc.go:87</code>).</li><li>I binding TS (<code>packages/workbench/wailsjs</code>, non versionati) nascono da <code>wails generate module</code>, eseguito da <code>task gen</code> (<code>Taskfile.yml:99-139</code>, precondizione <code>install-wails.sh --check</code>) e dallo stage 1 del Dockerfile del cloud (<code>services/cloud/Dockerfile:7-22</code>).</li><li>Build e rilascio passano da <code>wails build</code> (<code>scripts/release/build-desktop.sh:76-100</code>), dai template NSIS e <code>Info.plist</code> già nel repo (<code>apps/desktop/build/</code>), da <code>scripts/release/nsis-render.go</code> e da <code>apps/desktop/wails.json</code>.</li><li>Il single-instance usa <code>platform.InstanceID</code> = <code>dev.memobrain.desktop.&lt;16 hex&gt;</code> (<code>internal/platform/datadir.go:39-42</code>).</li><li>Il bundle iniziale del desktop è a 1979 kB su 2000 (<code>apps/desktop/frontend/scripts/esbuild.mjs:148</code>); il margine di 21 kB era condiviso con <a href="./0049-editor-live-milkdown.html">ADR-0049</a>; dal 2026-11-12 l&#39;entry è di 1376 kB e il margine è di circa 624 kB.</li></ul><p>La critica avversariale al piano, che non è versionata, ha verificato il progetto sul sorgente upstream di Wails <strong>v3.1.0</strong> (percorsi relativi a <code>v3/</code> nel repository <code>wailsapp/wails</code>, tag <code>v3.1.0</code>) e ha trovato rischi che il piano incorpora:</p><ul><li>ID single-instance incompatibile con D-Bus: <code>pkg/application/single_instance_linux.go</code> rifiuta ogni elemento che inizia con una cifra, e <code>application.go:207-221</code> trasforma l&#39;errore in <code>result.fatal</code>;</li><li>drop di file bloccato dal runtime: <code>@wailsio/runtime</code> (<code>src/window.ts</code>) registra all&#39;import listener in bubble su <code>document.documentElement</code> e, con <code>enableFileDrop</code> a <code>false</code>, imposta <code>dropEffect=&#39;none&#39;</code>; v2 impostava <code>&#39;copy&#39;</code> (<code>v2@v2.17.0</code>, <code>internal/frontend/runtime/desktop/draganddrop.js:61-65</code>);</li><li>menu nativo di default con «Learn More» che naviga a <code>wails.io</code>: <code>application.go:786-789</code> e <code>application_darwin.go:293-297</code> applicano <code>DefaultApplicationMenu()</code> (<code>menu_darwin_shared.go:13-22</code>, <code>roles.go:80-94</code> e <code>:156-164</code>);</li><li>segreti nei log a livello debug: <code>messageprocessor_call.go:126-131</code> serializza sempre argomenti e risultato;</li><li>limite di 64 MiB sul trasporto HTTP: <code>transport_http.go</code> fissa <code>maxRuntimeBodyBytes</code> (413 oltre);</li><li><code>wails3 dev</code> che forza <code>localhost</code> e una porta propria (<code>internal/commands/dev.go</code>);</li><li>Dockerfile e generatore su Linux: <code>pkg/application/application_linux.go:1</code> richiede cgo e GTK;</li><li><code>NewService[T any]</code> come unico costruttore di servizi (<code>pkg/application/services.go</code>);</li><li>ciclo di vita: <code>application.go:953-961</code> annulla il context dell&#39;app prima degli hook di chiusura; issue aperte upstream 6368, 6375, 6570 su chiusura e perdita di dati.</li></ul><p>Lo spike B-W0 ha poi riprovato molti di questi punti sul runtime (esiti in «Verificato e non»).</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p>Si migra a <strong>Wails v3.1.0 con pin esatto</strong> (ultima 3.x stabile alla data; la v3.0.0 è del 2026-10-26), dopo uno spike di fattibilità B-W0 sui tre sistemi operativi. Le decisioni B-D1…B-D12:</p><p><strong>B-D1 — L&#39;ABI del frontend non cambia.</strong> <code>window.go.app.*</code> e <code>window.runtime</code> restano. v3 ci arriva da un solo adattatore desktop, <code>apps/desktop/frontend/src/wailsHost.ts</code> (gemello di <code>installWailsGlobals</code>), con <code>@wailsio/runtime</code> a versione esatta, dipendenza del solo <code>apps/desktop/frontend</code>. Restano invariati <code>packages/workbench</code>, il bridge WASM, il mock, gli e2e e tutti i file che dipendono dai globali. Scartati i binding di <code>wails3 generate bindings</code>: cambiano nomi, modelli e trasporto, e il formato cambia a ogni minor.</p><p><strong>B-D2 — Un solo servizio Wails, <code>CoreBridge</code>, davanti a <code>rpc.Dispatcher</code>.</strong> Nuovo <code>apps/desktop/bridge.go</code>: <code>Call(service, method, args)</code> delega al dispatcher alimentato da <code>App.Services()</code>. Desktop e WASM passano dallo stesso dispatcher (parità ADR-0045 più forte di oggi). Registrare i 20 servizi uno per uno non è possibile: <code>NewService[T]</code> vuole un tipo concreto e <code>Services()</code> restituisce <code>[]any</code>. Gli errori restano <code>«code: text»</code>: lo shim rifiuta con la stringa e <code>errorCode(e) === &#39;conflict&#39;</code> resta valido.</p><p><strong>B-D3 — I binding TS nascono da un generatore Go</strong>, <code>internal/app/gen/bindings</code> (accanto a <code>gen/events</code> e <code>gen/capabilities</code>), con output <strong>byte-identico</strong> a quello di v2. <code>task gen</code>, <code>typecheck</code>, <code>parity</code> e <code>web-build</code> non richiedono più la CLI Wails; lo usa anche lo stage 1 del Dockerfile cloud (<code>CGO_ENABLED=0 go run ./internal/app/gen/bindings</code>). Il codice portato da v2 mantiene l&#39;attribuzione della sua licenza: la parte derivata da <code>typescriptify-golang-structs</code> (Tomo Krajina, <code>typescript.go</code>) è <strong>Apache-2.0</strong> (<code>LICENSE-typescriptify.txt</code>); il resto, derivato da Wails (<code>collect.go</code>, <code>emit.go</code> e il wrapper del runtime in <code>assets/</code>), è <strong>MIT</strong>, Copyright (c) 2018-Present Lea Anthony (<code>LICENSE-wails.txt</code>). Le due licenze stanno accanto al codice in <code>internal/app/gen/bindings</code>.</p><p><strong>B-D4 — Wails esce da <code>internal/app</code>.</strong> Host e <code>closeGuard</code> passano in un nuovo <code>internal/shell</code>. È obbligatorio: su Linux <code>v3/pkg/application</code> è cgo più GTK e il generatore non compilerebbe in Alpine. <code>go list -deps ./internal/app</code> non deve elencare <code>wailsapp</code>; <code>OnSecondInstance</code> prende <code>[]string</code>.</p><p><strong>B-D5 — Ciclo di vita.</strong></p><ul><li><code>Startup</code> riceve un context nostro, annullato dopo <code>Shutdown</code> (v3 annulla il proprio prima degli hook di chiusura; <code>internal/app/app.go:168-213</code> usa il context ovunque).</li><li><code>ServiceStartup</code> non restituisce mai errore: l&#39;errore di <code>app.db</code> si mostra su <code>ApplicationStarted</code>, come oggi.</li><li><code>Shutdown</code> idempotente, chiamato da più punti (copre la issue 6368).</li><li>Un solo <code>closeGuard</code> (stessa macchina a stati di <code>main.go:119-161</code>) agganciato all&#39;hook <code>WindowClosing</code> e a <code>ShouldQuit</code>, che non blocca mai il thread principale (la issue 6570 dice che su macOS il pulsante di chiusura non chiama <code>ShouldQuit</code>: lo copre l&#39;hook).</li><li>Watchdog: <code>os.Exit(0)</code> dopo 3 s se <code>Quit</code> resta appeso (issue 6375), altrimenti l&#39;updater Windows trova l&#39;exe bloccato.</li><li>I deep link restano in coda finché lo shim non emette un segnale esplicito, alla prima sottoscrizione a <code>app:open-request</code> (<code>packages/workbench/src/app/App.tsx:200</code>).</li></ul><p><strong>B-D6 — Single-instance e <code>memobrain://</code></strong> (aggiorna ADR-0001).</p><ul><li>Su Linux l&#39;ID attuale fa uscire l&#39;app all&#39;avvio in circa il 62% dei casi (D-Bus rifiuta gli elementi che iniziano con una cifra): l&#39;ID v3 è <code>dev.memobrain.desktop.i&lt;16 hex&gt;</code> (stesso hash, 64 bit, un prefisso <code>i</code> che inizia per lettera), con un test sulla regola D-Bus su 1000 data dir casuali (lo spike: ID attuale rifiutato in 614 casi su 1000, ID proposto accettato 1000/1000 e 1000 ID distinti). Va tenuta la chiave di cifratura derivata deterministicamente, non una chiave casuale su file.</li><li>Listener <code>ApplicationLaunchedWithUrl</code> solo su macOS; su Windows e Linux restano seconda istanza e <code>os.Args</code> (<code>main.go</code>), così non c&#39;è doppia consegna.</li><li><code>SecondInstanceData.Args</code> in v3 è l&#39;intero <code>os.Args</code>: va coperto da un test.</li></ul><p><strong>B-D7 — Menu e drop.</strong> Menu esplicito su macOS (App senza Services, Edit, Window), assemblato voce per voce (<code>explicitMenu()</code>) perché i ruoli grezzi di v3 differiscono da quelli di v2 (<code>AppMenu</code> aggiunge Services; <code>WindowMenu</code> ha «Bring All to Front» al posto di «Full Screen»; resta una differenza di etichetta, <code>Toggle Full Screen</code>); <strong><code>Menu.Set</code> si chiama solo su macOS</strong>, perché su Windows e Linux <code>applicationMenu</code> è applicato solo su darwin (<code>application.go:787</code>) e non c&#39;è barra. Nessuna barra su Linux e Windows (il menu di default di v3 aggiunge Reload, Zoom e un «Learn More» che naviga a <code>wails.io</code>, in contrasto con offline e architettura chiusa). Menu contestuale nativo disattivato, come in v2. <code>EnableFileDrop</code> a <code>false</code> e, nello shim, un <strong>drop-guard su <code>window</code></strong> (in bubble) che per i drag di file replica v2 (<code>preventDefault</code>, <code>dropEffect=&#39;copy&#39;</code>): senza, il runtime v3 blocca il drop verso l&#39;editor ed Excalidraw. Lo spike ha corretto il piano: il runtime v3 registra i suoi listener su <code>documentElement</code> e riporta <code>dropEffect</code> a <code>none</code> dopo il listener dell&#39;editor; un listener su <code>window</code> in bubble riporta il valore finale a <code>copy</code> nei 3 casi provati (zona editor, fuori zona, <code>dragenter</code>), quindi non servono né <code>body</code> né <code>stopPropagation</code>. Il drop vero da Finder, Explorer e Nautilus resta una prova manuale.</p><p><strong>B-D8 — Sicurezza.</strong> <code>cspMiddleware</code> e <code>csp_prod.go</code> invariati. <code>frame-src &#39;none&#39;</code> diventa un test, scritto sapendo che <strong>non copre gli iframe <code>srcdoc</code> e <code>about:blank</code></strong>, che caricano comunque (lo script inline in uno <code>srcdoc</code> resta bloccato dalla CSP; un iframe <code>https</code> e uno <code>wails://localhost/index.html</code> sono bloccati). <code>Options.Logger</code> dedicato <strong>a livello Warn minimo</strong>: <code>DisableLogging</code> da solo non basta (a livello debug v3 scrive argomenti e risultati di ogni chiamata, passphrase comprese: 3 occorrenze nello spike, 3 anche con il solo <code>DisableLogging</code>, 0 con il Logger a Warn), e <code>--log-level debug</code> esiste (<code>main.go:39</code>). Con il tag <code>production</code> e <code>Options.Logger</code> nullo Wails scarta tutto: sicuro, ma senza diagnostica. Ogni errore di binding è loggato a livello ERROR con il suo testo, quindi <strong>i messaggi di errore non devono contenere segreti</strong>. Il binario di rilascio non deve avere i tag <code>mcp</code>, <code>server</code>, <code>devtools</code> (controllo di rilascio).</p><p><strong>B-D9 — Build senza <code>wails3 build</code>.</strong> Nuovo <code>scripts/build-desktop-bin.sh</code>: <code>go build -tags production[,gtk3]</code> con output nel percorso di oggi (macOS con due build e <code>lipo</code>; Windows con <code>wails3 generate syso</code>). Dev: <code>wails3 tool watcher</code> con <code>FRONTEND_DEVSERVER_URL=http://127.0.0.1:5173</code> (<code>wails3 dev</code> forza <code>localhost</code> e una porta propria, incompatibile con ADR-0025). CLI <code>wails3</code> pinnata da <code>scripts/install-wails.sh</code>, che legge la versione da <code>apps/desktop/go.mod</code> (unico posto in cui si scrive); controllo di allineamento (anche di <code>@wailsio/runtime</code>) in <code>task lint</code>. <code>wails.json</code> diventa <code>build/project.json</code> più un <code>build/config.yml</code> minimo.</p><p><strong>B-D10 — Installer identici per costruzione.</strong> I template NSIS e <code>Info.plist</code> restano quelli del repo; <code>nsis-render.go</code> diventa <code>render-assets.go</code>. Restano invariati Bundle ID, chiavi di registro, nome dell&#39;eseguibile (<code>MemoBrain Notes.exe</code>) e percorso dei dati di WebView2. Il bootstrapper WebView2 si prende dal modulo v3; la <code>.app</code> macOS si assembla a mano (copia di <code>icon.icns</code>). Nomi e percorsi degli artefatti restano identici (updater, ADR-0023/0031).</p><p><strong>B-D11 — Linux con <code>-tags gtk3</code></strong> (WebKit2GTK 4.1): stesse dipendenze e stesse distribuzioni di oggi (oggi <code>-tags webkit2_41</code>, <code>build-desktop.sh:100</code>). <code>Linux.ProgramName: &quot;memobrain&quot;</code> per l&#39;icona nel dock. <code>golangci-lint</code> e <code>govulncheck</code> (<code>Taskfile.yml:153,164</code>) vanno eseguiti con lo stesso tag. GTK4/WebKitGTK 6.0 alzerebbe la base a Ubuntu 24.04 e Debian 13: non è parità, ADR futuro.</p><p><strong>B-D12 — Trasporto.</strong> HTTP di default, con tetto di 64 MiB per richiesta (413 oltre) contro i 256 MiB ammessi da <code>bindings_export.go:19</code> per l&#39;export HTML. Lo spike ha confermato il tetto (<code>SaveHTML</code> a 65 e 200 MiB fallisce con <code>Invalid runtime call: assembled body too large</code>, HTTP 422 in chunk e 413 con POST diretta; passa fino a 63 MiB): <strong>l&#39;onda B-W4b è attiva</strong>, con un trasporto proprio sul canale nativo dei messaggi verso lo stesso dispatcher, a CSP invariata. In alternativa si dichiara in un ADR un limite di export più basso.</p><h3 id="assunzioni-dichiarate-da-confermare-all-accettazione" tabindex="-1">Assunzioni dichiarate (da confermare all&#39;accettazione) <a class="header-anchor" href="#assunzioni-dichiarate-da-confermare-all-accettazione" aria-label="Permalink to &quot;Assunzioni dichiarate (da confermare all&#39;accettazione)&quot;">​</a></h3><ul><li>Il runtime JS di v3 resta <strong>fuori</strong> dal conteggio «initial» del bundle (chunk dinamico o servito dal Go), come il runtime iniettato di v2; altrimenti va alzato il limite di 2000 kB con una deviazione. Lo spike lo ha misurato: <code>@wailsio/runtime</code> 3.1.0 minificato pesa da 25 a 57 kB secondo gli import (25 kB con calls, events e application; 39 kB con Call e Events; 41 kB, 12 kB gzip, per uno shim con otto moduli; 56 kB il barrel completo), quindi 2004-2035 kB contro il limite di 2000 con il dato del piano (1979 kB): <strong>fallisce</strong> se il runtime resta nell&#39;entry.</li><li>L&#39;export HTML fino a 256 MiB è una funzione esistente e si mantiene (B-W4b se serve).</li><li><strong>Nessun rollback a v2</strong> (decisione dell&#39;owner, 2026-11-11): in caso di problemi gravi si corregge in avanti su v3. Il criterio di aggiornamento di M15 è l&#39;installazione manuale sopra la 1.3.4 su ogni sistema operativo, perché le build pubblicate non hanno l&#39;updater; l&#39;aggiornamento via updater si prova solo per build con chiave (la 1.3.4 ricostruita con chiave e URL di staging, <code>internal/updater/key.go:18-20</code>).</li></ul><h3 id="criteri-go-no-go-dello-spike-b-w0-tutti-sui-tre-os" tabindex="-1">Criteri go/no-go dello spike B-W0 (tutti, sui tre OS) <a class="header-anchor" href="#criteri-go-no-go-dello-spike-b-w0-tutti-sui-tre-os" aria-label="Permalink to &quot;Criteri go/no-go dello spike B-W0 (tutti, sui tre OS)&quot;">​</a></h3><p>Riportati nella roadmap (M15). GO solo se passano tutti. No-go su chiusura, deep link, aggiornamento, single-instance o drop senza rimedio in due giorni: si resta su v2.17.1 e si tengono B-W2 e B-W3 (generatore dei binding ed estrazione della shell, entrambe ancora su v2 e rilasciabili da sole).</p><h3 id="nessun-rollback-a-v2" tabindex="-1">Nessun rollback a v2 <a class="header-anchor" href="#nessun-rollback-a-v2" aria-label="Permalink to &quot;Nessun rollback a v2&quot;">​</a></h3><p><strong>Decisione dell&#39;owner (2026-11-11): nessun rollback a Wails v2.</strong> In caso di problemi gravi (un P0 della matrice: perdita dati alla chiusura, login o deep link rotti, installazione sopra la 1.3.4 fallita, crash all&#39;avvio) si corregge in avanti su v3 con una nuova versione. Non si prepara né si prova un rilascio v2 di ritorno, e non serve un ramo o un tag di appoggio. I rilievi 1 e 2 della revisione B-W9 (base del rollback e percorso di aggiornamento reale) sono chiusi da questa decisione e dal criterio di M15 qui sotto; B-W2 e B-W3 (generatore dei binding ed estrazione della shell) restano comunque nel codice.</p><p><strong>Criterio di aggiornamento di M15 (decisione dell&#39;owner, 2026-11-11).</strong> Le build pubblicate non hanno l&#39;updater (<code>.github/workflows/release.yml:112</code> imposta <code>ALLOW_UNSIGNED_UPDATES: &#39;1&#39;</code>, senza <code>UPDATE_PUBLIC_KEY</code>): il criterio è l&#39;<strong>installazione manuale sopra la 1.3.4</strong> su ogni sistema operativo (<code>docs/qa/m15-wails3-matrice.md</code> §1.1). L&#39;aggiornamento via updater (§3 della matrice) resta da provare solo per le build compilate con una chiave.</p><h3 id="cambiamenti-visibili-all-utente" tabindex="-1">Cambiamenti visibili all&#39;utente <a class="header-anchor" href="#cambiamenti-visibili-all-utente" aria-label="Permalink to &quot;Cambiamenti visibili all&#39;utente&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Funzione</th><th>Con v3</th></tr></thead><tbody><tr><td>Strumenti recenti di Excalidraw (<code>drawing/ToolsPanel.tsx:18-28</code>)</td><td>Su macOS e Linux l&#39;elenco si azzera una volta: l&#39;origine passa da <code>wails://wails</code> a <code>wails://localhost</code></td></tr><tr><td>Chiamata a un binding che va in panic</td><td>La promise ora viene rifiutata; in v2 non si risolveva mai</td></tr><tr><td>Minimo di macOS</td><td>13 (prima <code>Info.plist</code> dichiarava 10.13): su macOS 12 o precedente il Finder rifiuta l&#39;app, vedi «Stato dell&#39;implementazione»</td></tr><tr><td>Tutto il resto</td><td>Invariato, con voce nella matrice di QA</td></tr></tbody></table><h3 id="stato-dell-implementazione-b-w2-b-w7-2026-11-11" tabindex="-1">Stato dell&#39;implementazione (B-W2…B-W7, 2026-11-11) <a class="header-anchor" href="#stato-dell-implementazione-b-w2-b-w7-2026-11-11" aria-label="Permalink to &quot;Stato dell&#39;implementazione (B-W2…B-W7, 2026-11-11)&quot;">​</a></h3><p>Le decisioni B-D1…B-D12 sopra sono quelle del piano. Qui sono fissate quelle effettive, e dove l&#39;implementazione le ha cambiate è detto esplicitamente. Wails è a <strong>v3.1.0 con pin esatto</strong> (<code>apps/desktop/go.mod</code>, <code>@wailsio/runtime</code> 3.1.0 in <code>apps/desktop/frontend/package.json</code>); la v3.1.0 è ancora l&#39;ultima stabile (3.2.0 esiste solo come nightly). Il generatore dei binding (B-W2, <code>internal/app/gen/bindings</code>) dà output byte-identico a <code>wails generate module</code> v2: <code>regen-golden.sh</code> fissa <code>WAILS_V2=v2.17.1</code> e richiede la rete o una cache che contenga già quella versione.</p><p><strong>Ponte e shim (B-D1, B-D2).</strong></p><ul><li><code>CoreBridge</code> (<code>apps/desktop/bridge.go</code>) è l&#39;unico servizio Wails: <code>Call(service, method, args)</code>, <code>Methods()</code>, <code>DomReady()</code>, più <code>BeginUpload</code>, <code>AbortUpload</code> e <code>CallUploaded</code> per i payload grandi; <code>ServiceStartup</code> e <code>ServiceShutdown</code> non sono esposti come binding. Non è nell&#39;elenco di <code>App.Services()</code>, quindi <code>task gen</code>, il registro di parità e i binding TS non cambiano. Gli argomenti viaggiano come <strong>array JSON annidato</strong> (<code>[&quot;SettingsAPI&quot;,&quot;Capabilities&quot;,[]]</code>), non come <code>JSON.stringify(args)</code>: <code>Call</code> prende un <code>json.RawMessage</code>, e una stringa verrebbe rifiutata dal dispatcher.</li><li>Lo shim <code>apps/desktop/frontend/src/wailsHost.ts</code> installa <code>window.go.app.&lt;Service&gt;.&lt;Method&gt;</code> e <code>window.runtime</code> (le 9 funzioni usate) sopra <code>@wailsio/runtime</code>; l&#39;elenco dei metodi viene da <code>CoreBridge.Methods()</code>, gli errori sono rifiutati con la stringa del messaggio (<code>errorCode(e) === &#39;conflict&#39;</code> resta valido), gli eventi passano da <code>Events.On</code>. <code>EventsEmit</code> invia solo il primo argomento (il runtime v3 prende un dato solo; il workbench non lo usa). <code>main.tsx</code> lo carica con <code>import()</code> fuori da <code>MEMOBRAIN_E2E</code>: il runtime sta in un chunk a parte (57.241 byte, 17,6 kB gzip) che <code>checkBudget</code> non conta, quindi <strong>l&#39;assunzione «runtime fuori dall&#39;entry» è confermata</strong> (build finale: iniziale 1990 kB su 2000 al momento di B-W5). Se l&#39;installazione fallisce compare un messaggio fisso (it/en) invece di una finestra bianca: è l&#39;unico testo fuori da i18n. 33 test vitest.</li><li><strong>Drop-guard</strong> su <code>window</code> (in bubble): per i drag di file imposta <code>dropEffect=&#39;copy&#39;</code> su <code>dragenter</code> e <code>dragover</code>; sul <code>drop</code> fa solo <code>preventDefault</code>. <code>EnableFileDrop</code> è <code>false</code> e il menu contestuale nativo è disattivato.</li><li><code>DomReady</code> si chiama alla prima sottoscrizione a <code>app:open-request</code>; ripeterlo è innocuo (vale anche dopo <code>location.reload()</code>), e finché non arriva i deep link restano in coda.</li></ul><p><strong>Ciclo di vita, chiusura e shell (B-D4, B-D5).</strong></p><ul><li>Host, <code>closeGuard</code>, lifecycle, menu, ascolto degli URL e controllo dei tag stanno in <code>internal/shell</code>; <code>go list -deps ./internal/app</code> non elenca <code>wailsapp</code>. Il context è nostro e <code>Stop</code> è idempotente.</li><li><strong>Watchdog</strong> di 3 s con <code>os.Exit(0)</code>: si arma solo quando il guard lascia passare una richiesta (seconda richiesta o timeout), non al primo <code>Quit</code> con guard inattivo, perché in quel caso (per esempio dall&#39;updater) taglierebbe a 3 s un flush che il guard aspetta fino a 10 s: perdita di dati (D-04). <code>ErrorDialog</code> mette in coda le richieste fatte prima di <code>ApplicationStarted</code>.</li><li>v3 reagisce solo al primo SIGTERM/SIGINT: quel segnale passa dal guard e il processo aspetta il flush del frontend (0,12 s con lo shim, 10 s senza).</li><li><strong>Single-instance</strong> (B-D6): ID <code>dev.memobrain.desktop.i&lt;16 hex&gt;</code>; la chiave di cifratura deriva dall&#39;ID (<code>platform.InstanceKey</code>), nessun file <code>instance.key</code>. Il 614/1000 dello spike è il rifiuto dell&#39;ID precedente da parte della regola D-Bus di v3, copiata verbatim (il file upstream è solo Linux): su Ubuntu non è stata provata.</li><li><strong>Menu</strong> (B-D7): <code>Menu.Set</code> solo su macOS, con un menu esplicito (App senza Services, Edit, Window; l&#39;etichetta resta «Toggle Full Screen»); su Windows e Linux nessuna barra.</li><li><strong>Log</strong> (B-D8, corretto): <code>Options.Logger</code> è <code>telemetry.UIRuntimeLogger</code>, con minimo Warn <strong>e</strong> con lo scarto dei record il cui messaggio inizia per <code>Binding call failed: Bound method returned an error</code>. Il piano accettava che ogni errore di binding finisse nel log a livello ERROR; ma quel testo contiene path relativi al vault, anche di vault privati, e i log finiscono nei bundle di supporto. Restano nel log un metodo sconosciuto, argomenti errati, un panic in un metodo legato e ogni altro warning o errore; l&#39;errore arriva comunque alla UI. <strong>Il filtro dipende dal testo di v3.1.0</strong>: un aggiornamento di Wails che lo cambia lo spegne in silenzio; va aggiornato insieme alla stringa del test <code>TestUIRuntimeLoggerDropsTheErrorsOfBoundMethods</code>. Inoltre un binario con tag <code>production</code> e uno fra <code>mcp</code>, <code>server</code>, <code>devtools</code> rifiuta di partire (<code>ForbiddenBuildTags</code>).</li><li><strong>Dialoghi di file e cartella.</strong> Su Windows v3 restituisce l&#39;errore «cancelled by user» quando l&#39;utente annulla, mentre v2 lo filtrava: <code>dialogAnswer</code> lo traduce in <code>(&quot;&quot;, nil)</code>, come su macOS e Linux (confronto sul testo, perché il pacchetto <code>cfd</code> è interno). Il test copre solo l&#39;helper, non un dialogo vero. I dialoghi sono agganciati alla finestra (foglio su macOS; proprietario su Windows e Linux): v2 probabilmente non lo faceva, da provare.</li></ul><p><strong>Export oltre 64 MiB (B-D12, B-W4b): scelta diversa dal piano.</strong> Non c&#39;è un trasporto proprio sul canale nativo (<code>RawMessageHandler</code>/<code>Options.Transport</code> obbligano a riscrivere anche risposte ed eventi, con limiti per WebView non misurabili): il tetto di 64 MiB di <code>transport_http.go</code> riguarda la sola richiesta, e le risposte da 100 MiB passano già. Lo shim manda gli argomenti oltre <strong>32 MiB di JSON</strong> (byte UTF-8) a pezzi di 512 KiB (<code>Uint8Array</code>: WebKitGTK va in crash con un body <code>Blob</code> verso uno schema custom) a <code>/memobrain/upload/&lt;id&gt;?offset=n</code> dell&#39;asset server, sulla stessa origine di <code>/wails/runtime</code>, quindi la CSP resta invariata, e poi chiama <code>CallUploaded(service, method, id)</code>. La firma dei binding non cambia. Tetto lato Go 320 MiB (256 MiB dell&#39;export più l&#39;escape JSON); i byte restano in RAM, mai su disco (un file temporaneo con una nota di un vault privato resterebbe dopo un crash); al massimo 2 upload in corso e 640 MiB riservati; un upload inattivo scade dopo 30 s e un chunk rifiutato lo scarta; l&#39;id è casuale a 128 bit e funge da capability, e <code>CallUploaded</code> esegue gli stessi controlli di <code>Call</code>. Misure su macOS (WKWebView reale, CSP di produzione): 65 MiB in 0,63 s, 200 MiB in 2,0 s, 250 MiB con caratteri non ASCII in 3,1 s con checksum corretto; una chiamata pendente di 180 s con altre 8 da 90-125 s e due upload durante l&#39;attesa: tutte risolte; picco di memoria del WebContent circa 2,5 GiB e del lato Go circa 1,4 GiB. <code>checkStandaloneHTML</code> impiega circa 3 s ogni 65 MiB con molti tag o un grosso data URI, quindi una chiamata da 200 MiB può durare 10 s o più, qualunque sia il trasporto. Il test sotto <code>-race</code> si limita a 65 MiB (a 255 MiB servono oltre 40 s).</p><p><strong>Build e dev (B-D9).</strong></p><ul><li><code>scripts/build-desktop-bin.sh</code> (opzioni <code>--os</code>, <code>--arch</code>, <code>--version</code>, <code>--ldflags</code>, <code>--skip-frontend</code>, <code>--dev</code>, <code>--run-dev</code>) esegue <code>go build -tags production</code> (più <code>gtk3</code> su Linux) nel percorso di prima; su macOS fa due build, <code>lipo</code> e firma ad hoc con <code>MACOSX_DEPLOYMENT_TARGET=13.0</code>; su Windows usa <code>wails3 generate syso</code> con il manifest reso come <code>info.json</code>. Un difetto trovato e corretto: <code>wails.exe.manifest</code> è un template e veniva passato non reso, quindi il loader di Windows avrebbe rifiutato l&#39;exe. Le <code>-X</code> dell&#39;updater non sono lette dallo script: arrivano da <code>--ldflags</code> o <code>LDFLAGS_EXTRA</code>, e la politica «niente release senza chiave» resta in <code>scripts/release/build-desktop.sh</code>.</li><li>Con <code>--dev</code> lo script passa <code>-X main.Version=dev</code> (updater spento, log su console): il <code>git describe</code> serve solo all&#39;<code>Info.plist</code> e al log dello script. Con <code>git describe</code> nell&#39;<code>-X</code> l&#39;updater resterebbe attivo e la 1.3.4 stabile risulterebbe più nuova.</li><li><code>task dev-desktop</code> lancia <code>wails3 tool watcher</code> con <code>FRONTEND_DEVSERVER_URL=http://127.0.0.1:5173</code> in tre passi: esbuild in background con readiness <strong>HTTP</strong> su <code>http://127.0.0.1:5173/</code> (risponde 404 finché <code>dist/index.html</code> non c&#39;è, così il passo Go parte a bundle scritto: con una readiness TCP l&#39;avvio da <code>dist</code> assente era intermittente), build Go bloccante con <code>--dev</code>, app con <code>--run-dev</code>; su macOS l&#39;app dev gira nel bundle <code>memobrain.dev.app</code> (<code>Info.dev.plist</code>). <code>SKIP_FRONTEND</code> salta il frontend solo con valore <code>1</code> e con <code>--release</code> è rifiutato.</li><li><code>wails.json</code> è sostituito da <code>apps/desktop/build/project.json</code> e da un <code>build/config.yml</code> minimo; <code>scripts/install-wails.sh</code> legge la versione di v3 da <code>apps/desktop/go.mod</code>, e <code>task lint-wails-versions</code> (in <code>task lint</code>, con <code>--check-pins</code>) fallisce se <code>go.mod</code>, il runtime npm o la CLI non coincidono. <code>UniformTypeIdentifiers</code> lo linka v3 da sé: nessun <code>CGO_LDFLAGS</code> manuale.</li></ul><p><strong>Rilascio (B-D10).</strong> <code>scripts/release/build-desktop.sh</code> poggia su <code>build-desktop-bin.sh</code>; <code>scripts/release/render-assets.go</code> rende <code>Info*.plist</code>, <code>windows/info.json</code> e <code>wails_tools.nsh</code> da <code>build/project.json</code> e <strong>sostituisce <code>nsis-render.go</code></strong> (rimosso); su Windows l&#39;installer si assembla in una cartella temporanea, senza toccare il repository, e <code>wails_tools.nsh</code> reso è identico byte per byte a quello di v2. Il bootstrapper WebView2 viene da <code>wails3 generate webview2bootstrapper</code> (stesso SHA-256 della copia nel modulo v2) con il pin in <code>scripts/release/checksums.sha256</code>. <code>scripts/release/check-build-tags.sh</code> controlla ogni slice del binario (presente <code>production</code>; assenti <code>mcp</code>, <code>server</code>, <code>devtools</code>); su Linux si controlla che il binario linki <code>libwebkit2gtk-4.1</code> e non GTK4; <code>package-macos.sh</code> cerca esattamente <code>&lt;name&gt;.app</code> da <code>project.json</code>. In <code>release.yml</code> la CLI <code>wails3</code> si installa e si mette in cache solo su Windows, e <code>--check-pins</code> gira su tutti gli OS. Nomi e percorsi degli artefatti sono invariati (test <code>build/assets_test.go</code>: nessun segnaposto residuo nei cinque template, Bundle ID, <code>CFBundleExecutable memobrain</code>, <code>UNINST_KEY</code>, <code>Software\\Classes\\memobrain</code>, <code>PRODUCT_EXECUTABLE</code>).</p><p><strong>Minimo di macOS: da 10.13 a 13.0 (B-D10, corretto).</strong> Il piano lasciava l&#39;<code>Info.plist</code> invariato; l&#39;implementazione porta <code>LSMinimumSystemVersion</code> di <code>Info.plist</code> e <code>Info.dev.plist</code> da <code>10.13.0</code> a <code>13.0.0</code> (fissato dal test). Il motivo: il linker di Go 1.27 dichiara macOS 13.0 come la versione più vecchia supportata (<code>cmd/link/internal/ld/macho.go:449</code>) e compila gli oggetti per quella; i binari v3 hanno <code>minos 13.0</code> su entrambe le slice, e 10.13.0 prometteva un avvio che <code>dyld</code> rifiuta. <strong>Controllo sulla build v2 con Go 1.27</strong> (verifica fatta il 2026-11-11 su una copia locale della 1.3.4, compilata con Go 1.27.3 e Wails v2.17.0, con <code>vtool</code> e <code>go version -m</code>): la slice x86_64 dichiarava <code>LC_VERSION_MIN_MACOSX 10.13</code> e la slice arm64 <code>minos 11.0</code>, perché la CLI v2 aggiunge <code>-mmacosx-version-min=10.13</code> ai flag di cgo (<code>v2@v2.17.1/pkg/commands/build/base.go:312-313</code> e <code>:351-352</code>). Quindi il minimo <strong>dichiarato</strong> della 1.3.4 era 10.13 su Intel e 11.0 su Apple Silicon, ma Go 1.27 dichiara di supportare macOS 13 e oltre: quel 10.13 non era una promessa verificata, e non è stato provato un avvio della 1.3.4 su macOS 10.13–12. La novità visibile è che su macOS 12 o precedente il Finder ora rifiuta l&#39;app (serve macOS 13), mentre prima il sistema la lasciava avviare.</p><p><strong>Matrice di QA.</strong> <code>docs/qa/m15-wails3-matrice.md</code> contiene la matrice manuale per sistema operativo (§0 come costruire i binari, §1 installazione e installazione manuale sopra la 1.3.4, che è il criterio di aggiornamento, §2 funzioni con priorità P0/P1/P2: chiusura, deep link, drop, dialoghi con «Annulla», export grandi, single-instance su Linux, menu, stampa, aggiornamento; §3 la procedura 1.3.4 → v3 via updater su un canale HTTPS di staging, solo per build con chiave, perché l&#39;updater rifiuta <code>http</code> anche su loopback) e il registro degli esiti. Stato al 2026-11-11: provato su macOS (build e pacchetto) e come cross-build Windows; <strong>tutto il resto della matrice non è mai stato eseguito</strong>.</p><p><strong>Aggiornamento dei documenti.</strong> Citano ancora Wails v2, <code>wails build</code>, <code>wails dev</code>, <code>wails doctor</code> o il tag <code>webkit2_41</code> (verificato il 2026-11-11): <code>README.md</code>, <code>CONTRIBUTING.md</code>, <code>docs/dev-setup.md</code>, <code>docs/architecture.md</code>, <code>deploy/PINS.md</code>, <code>CLAUDE.md</code>, <code>ADR-0001</code>, <code>ADR-0005</code>, <code>ADR-0023</code>, <code>ADR-0031</code> e <code>ADR-0036</code>. Va aggiornato anche <code>docs/roadmap.md</code> dove cita il rinvio a v2.</p><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Restare su Wails v2.</strong> Scartata dall&#39;utente; resta il ripiego se lo spike dà no-go (con v2 portata a 2.17.1, fix di sicurezza Linux).</li><li><strong>Binding di <code>wails3 generate bindings</code> e registrazione dei 20 servizi uno per uno.</strong> Scartata: cambia nomi e modelli, tocca tutti i file che dipendono dai globali, e <code>NewService[T]</code> non accetta <code>[]any</code>.</li><li><strong>Aggiungere un secondo elenco di servizi per v3.</strong> Scartata: due elenchi si disallineano; <code>App.Services()</code> resta l&#39;unico.</li><li><strong>Lasciare Wails in <code>internal/app</code>.</strong> Scartata: su Linux il generatore dei binding e il Dockerfile non compilerebbero (cgo più GTK).</li><li><strong><code>wails3 build</code> e <code>wails3 dev</code> come entry point.</strong> Scartata: Taskfile generati, <code>dev</code> forza <code>localhost</code> (ADR-0025), duplica la versione.</li><li><strong>GTK4/WebKitGTK 6.0.</strong> Rinviata: alza la base delle distribuzioni, non è parità.</li><li><strong>Chiave di cifratura del single-instance casuale su file</strong> (<code>instance.key</code>). Scartata: comportamento nuovo con nuovi modi di guasto.</li><li><strong>Un trasporto proprio fin da subito.</strong> Rinviata: si decide dopo la misura dello spike (B-W4b).</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Parità funzionale con un solo adattatore desktop nuovo (shim) e un solo servizio Wails (<code>CoreBridge</code>); più codice generato da noi (binding) e meno dipendenza dalla CLI di Wails; il workbench web e il core WASM non cambiano.</li><li>La migrazione introduce rischi che v2 non aveva: chiusura con perdita di dati su Windows (issue upstream 6368, 6375, 6570), issue sui dialoghi di file (6355, 6558) e sul trasferimento di binari su Windows (6530, 6550), minor settimanali di v3 con API instabili. Mitigazioni: guard su due punti, <code>Shutdown</code> idempotente, watchdog, pin esatti, superficie Wails in pochi file.</li><li>Nessun rollback a v2: i problemi gravi si correggono in avanti su v3. La prova di aggiornamento che conta è l&#39;installazione manuale sopra la 1.3.4; quella via updater (1.3.4 → v3, canale di staging) vale solo per build con chiave.</li><li>Costi: il runtime (circa 60 kB) pesa sul bundle se non è escluso; il formato dei log di Wails richiede un logger dedicato; <code>golangci-lint</code> e <code>govulncheck</code> richiedono il tag <code>gtk3</code> su Linux.</li><li><strong>Da aggiornare quando l&#39;ADR sarà accettato:</strong> ADR-0001 (testo «Wails v2 (2.12)» e consegna URL), ADR-0005, ADR-0023, ADR-0025, ADR-0029, ADR-0030, ADR-0031, ADR-0045, ADR-0048; <code>docs/adr/README.md</code>; <code>CONTRIBUTING.md</code>, <code>docs/desktop-web-sync.md</code>, <code>docs/release/README.md</code>, <code>docs/dev-setup.md</code>, <code>CLAUDE.md</code> (comandi); CHANGELOG (sezione «Compatibilità»). <code>Specifications.md</code> va aggiornato dall&#39;owner nei punti elencati sopra.</li></ul><h2 id="verificato-e-non" tabindex="-1">Verificato e non <a class="header-anchor" href="#verificato-e-non" aria-label="Permalink to &quot;Verificato e non&quot;">​</a></h2><p><strong>Verificato sul repository (2026-11-10, sul commit <code>bd9efc3</code>, prima dell&#39;inizio delle onde; i numeri di riga possono spostarsi):</strong> versione reale v2.17.0 (<code>go.mod:19</code>); import Wails confinati in <code>main.go</code> e <code>host_wails.go</code>; <code>App.Services()</code>, <code>rpc.Dispatcher</code>, <code>Options.Host</code>; <code>InstanceID</code> con prefisso <code>dev.memobrain.desktop.</code> + 16 hex; <code>closeGuard</code> in <code>main.go</code>; <code>Dockerfile:7-22</code> che esegue <code>wails generate module</code>; <code>Taskfile.yml</code> con <code>gen-wails</code> e il tag <code>webkit2_41</code>; CSP di produzione con <code>frame-src &#39;none&#39;</code>; tetto <code>maxExportHTML = 256 &lt;&lt; 20</code>; <code>wails.json</code> e <code>nsis-render.go</code> esistenti; bundle 1979/2000 kB (roadmap M13).</p><p><strong>Letto sul sorgente upstream v3.1.0 dalla critica:</strong> <code>single_instance_linux.go</code> rifiuta gli elementi D-Bus che iniziano con una cifra; <code>application.go</code> annulla il context prima degli hook di shutdown; <code>maxRuntimeBodyBytes = 64 MiB</code> in <code>transport_http.go</code>; <code>DefaultApplicationMenu()</code> con Reload, Zoom e «Learn More»; <code>messageprocessor_call.go</code> serializza argomenti e risultato nel log di debug; <code>wails3 dev</code> usa <code>localhost</code>; <code>NewService[T]</code> accetta solo un tipo concreto; <code>gtk3</code> resta tag opt-in; il runtime di produzione pesa 59.725 byte; <code>mcp_enabled.go</code> apre un server su <code>127.0.0.1:9099</code>; il bootstrapper WebView2 esiste nel modulo. Lo spike ha riprovato sul runtime i punti sull&#39;ID, il menu, il logger, il tetto dei 64 MiB e il drop (sotto).</p><h3 id="esito-dello-spike-b-w0-wails-v3-1-0-solo-macos-criterio-per-criterio" tabindex="-1">Esito dello spike B-W0 (Wails v3.1.0, solo macOS), criterio per criterio <a class="header-anchor" href="#esito-dello-spike-b-w0-wails-v3-1-0-solo-macos-criterio-per-criterio" aria-label="Permalink to &quot;Esito dello spike B-W0 (Wails v3.1.0, solo macOS), criterio per criterio&quot;">​</a></h3><p>Lo spike è un modulo annidato con un suo <code>go.work</code> (<code>apps/desktop/spike/wails3/</code> in un worktree, non unito): <code>CoreBridge</code> davanti a <code>rpc.Dispatcher</code> con la vera <code>App.Services()</code> e un host finto; app reale in un WKWebView con la CSP di produzione; modalità server headless con una sonda HTTP. <strong>Raccomandazione dello spike: GO con condizioni.</strong> Su macOS non c&#39;è nessun bloccante; restano da risolvere export oltre 64 MiB, budget del bundle e prove manuali su Windows e Linux. Non sono state provate WebView2 e WebKitGTK.</p><table tabindex="0"><thead><tr><th>#</th><th>Esito</th><th>Misure</th></tr></thead><tbody><tr><td>1</td><td><strong>parziale</strong> (trasporto, macOS)</td><td><code>Call.ByName(&quot;main.CoreBridge.Call&quot;)</code> funziona con OpenVault, WriteNote e ReadNote reali; il conflitto arriva come <code>RuntimeError</code> con <code>conflict: file changed on disk</code> e <code>errorCode(e)</code> dà <code>conflict</code>; gli eventi Go→JS arrivano come <code>{name,data}</code> (nil diventa <code>null</code>); le panic diventano promise rifiutate e il server resta vivo. <strong>Non verificabile qui:</strong> la UI vera con <code>wailsHost.ts</code> (non scritto, è B-W5), Windows e Linux</td></tr><tr><td>2</td><td><strong>passa</strong> su macOS (40/40)</td><td>Dieci prove per ciascuno di quattro gesti: <code>Window.Close</code>, <code>App.Quit</code>, <code>performClose:</code> (pulsante rosso) e <code>terminate:</code> (Cmd+Q). File scritto ogni volta, <code>app:before-close</code> una sola volta, processo terminato in circa 0,7 s; con <code>performClose:</code> l&#39;hook <code>WindowClosing</code> scatta (il caso della issue 6570 non si riproduce). <strong>Non verificabile qui:</strong> Alt+F4, Windows, Quit dall&#39;updater, frontend appeso, tasti fisici</td></tr><tr><td>3</td><td><strong>non verificabile qui</strong></td><td>Servono bundle, registro e <code>.desktop</code>. Dal sorgente: su Windows e Linux <code>run()</code> emette <code>ApplicationLaunchedWithUrl</code> quando <code>os.Args</code> contiene un solo URL (<code>application_windows.go:164</code>, <code>application_linux_gtk3_shared.go:40</code>); <code>SecondInstanceData.Args</code> è l&#39;intero <code>os.Args</code>, più l&#39;URL catturato su macOS</td></tr><tr><td>4</td><td><strong>premessa confermata</strong>, test Linux non eseguibile</td><td><code>platform.InstanceID</code> attuale rifiutato dalla regola D-Bus nel 61,4% dei casi (614/1000); <code>dev.memobrain.desktop.i&lt;16 hex&gt;</code> accettato 1000/1000 con 1000 ID distinti. La regola D-Bus è una copia verbatim (il file upstream è solo Linux): su Ubuntu non è stato provato</td></tr><tr><td>5</td><td><strong>parziale</strong></td><td>Con <code>enableFileDrop</code> a <code>false</code> il runtime riporta <code>dropEffect</code> a <code>none</code> dopo il listener dell&#39;editor (confermato). Un listener su <code>window</code> in bubble riporta <code>copy</code> in 3 casi su 3. Il drop vero da Finder, Explorer e Nautilus è manuale</td></tr><tr><td>6</td><td><strong>passa</strong> su macOS (struttura), parziale altrove</td><td>Menu sorgente: App senza Services; Edit con Undo, Redo, Cut, Copy, Paste, Paste and Match Style, Delete, Select All, Speech; Window con Minimize, Zoom, <code>Toggle Full Screen</code>. Su Windows e Linux nessuna barra (<code>application.go:787</code>). Controllo visivo non fatto</td></tr><tr><td>7</td><td><strong>passa</strong> con <code>Options.Logger</code> a Warn minimo</td><td>A livello debug gli argomenti compaiono nel log (3 occorrenze, passphrase inclusa); con il Logger a Warn non compaiono; <code>DisableLogging</code> da solo non basta (3 occorrenze); un errore con il segreto nel messaggio finisce comunque nel log a livello ERROR</td></tr><tr><td>8</td><td><strong>fallisce</strong> oltre 64 MiB</td><td>Passano <code>SaveAttachment</code> da 32 MB (557 ms), <code>SaveHTML</code> fino a 63 MiB (sotto 0,9 s) e risposte da 100 MiB. <code>SaveHTML</code> a 65 e 200 MiB fallisce con <code>Invalid runtime call: assembled body too large</code> (HTTP 422 in chunk, 413 con POST diretta), anche nel WKWebView reale. Una chiamata pendente per 3 minuti con altre 8 (90-125 s) passa in WKWebView; in modalità server solo alzando i timeout (il default di 30 s non vale per il desktop). Serve B-W4b. <strong>Non verificabile qui:</strong> WebView2 e WebKitGTK</td></tr><tr><td>9</td><td><strong>passa</strong> su macOS, con una riserva</td><td>Origine <code>wails://localhost</code>, header CSP invariato, <code>connect-src &#39;self&#39;</code> copre <code>/wails/runtime</code>. 4 violazioni, tutte attese (iframe https, iframe <code>wails://localhost/index.html</code>, fetch esterno, script inline). Riserva: gli iframe <code>srcdoc</code> e <code>about:blank</code> caricano comunque sotto <code>frame-src &#39;none&#39;</code>. Su Windows l&#39;origine è <code>http://wails.localhost</code> (dal sorgente)</td></tr><tr><td>10</td><td><strong>parziale</strong></td><td>Con <code>FRONTEND_DEVSERVER_URL=http://127.0.0.1:5173</code> in una build non production la pagina arriva dal proxy e il canale di ricarica SSE funziona (3 s); origine in dev <code>wails://localhost:5173</code>. Non provati il watcher Go e <code>wails3 dev</code></td></tr><tr><td>11</td><td><strong>non verificabile qui</strong></td><td>Aggiornamento 1.3.4 → v3 su staging (criterio rivisto il 2026-11-11: il ritorno a v2 è escluso, vedi «Nessun rollback a v2»; l&#39;aggiornamento via updater vale solo per build con chiave)</td></tr><tr><td>12</td><td><strong>non verificabile qui</strong></td><td>Titlebar, scorciatoie, About, fullscreen, stampa, dialoghi di file e cartella</td></tr></tbody></table><p><strong>Compilazione.</strong> darwin compila e gira (v2 e v3 convivono nel link solo perché <code>internal/app</code> importa ancora v2; con B-D4 sparisce). windows/amd64 compila con <code>CGO_ENABLED=0</code>. linux/amd64 con <code>-tags gtk3</code> non è cross-compilabile da qui (cgo, GTK, sysroot); compila con <code>CGO_ENABLED=0 -tags production,purego</code> e con <code>-tags server</code>, quindi il codice Go tipizza, ma il backend purego è sperimentale e non è quello del piano. <code>go test -race</code> su <code>idrule</code> e sul package principale passa; <code>go vet</code> pulito con <code>-tags production</code> e con <code>-tags server</code>. Il <code>json.Marshal</code> incondizionato di Wails costa 92 ms su 63 MiB.</p><p><strong>Decisioni corrette dallo spike</strong> (già riportate sopra): drop-guard su <code>window</code>, non su <code>body</code> con <code>stopPropagation</code> (B-D7); <code>Menu.Set</code> solo su macOS (B-D7); <code>Options.Logger</code> a Warn minimo, perché <code>DisableLogging</code> da solo non basta (B-D8); gli iframe <code>srcdoc</code> e <code>about:blank</code> non sono coperti da <code>frame-src &#39;none&#39;</code> (B-D8); ID single-instance <code>dev.memobrain.desktop.i&lt;16 hex&gt;</code> (B-D6); B-W4b attiva (B-D12); runtime fuori dall&#39;entry o limite alzato (assunzioni).</p><p><strong>Condizioni per il GO.</strong> Export oltre 64 MiB risolto (B-W4b o limite dichiarato); runtime fuori dall&#39;entry (import dinamico o <code>/wails/runtime.js</code> servito da Go) o nuovo limite di bundle in un ADR; prove manuali su macOS, Windows e Linux (chiusura 20 volte per OS anche con frontend appeso, <code>memobrain://</code> a freddo e a caldo 10/10, drop reale, dialoghi, <code>SaveHTML</code> da 63 MiB e chiamata pendente di 3 minuti su WebView2 e WebKitGTK, single-instance su Ubuntu 22.04 e 24.04 con 50 data dir, icona nel dock su X11 e Wayland, installazione manuale sopra la 1.3.4 su ogni sistema operativo (aggiornamento via updater su staging solo per build con chiave; nessun ritorno a v2), ricarica del lato Go con <code>wails3 tool watcher</code>).</p><p><strong>Ancora da chiudere</strong> (non coperto dallo spike): se <code>ErrorDialog</code> da <code>ServiceStartup</code> stalla (assunto: va spostato su <code>ApplicationStarted</code>); <code>wails3 generate syso</code> in cross da macOS per l&#39;installer Windows; comportamento delle webview su Windows e Linux (menu, <code>navigator.clipboard</code> su <code>wails://localhost</code>, titlebar, icona nel dock).</p><p><strong>Dopo B-W7 (2026-11-11).</strong> Esiste un&#39;implementazione completa su macOS; non esiste nessuna prova su Windows e Linux oltre a un cross-build Windows.</p><p><strong>Verificato (macOS arm64, Go 1.27, Wails 3.1.0):</strong> <code>go test -race -count=1 ./...</code> di <code>apps/desktop</code> (compresi <code>main</code>, <code>shell</code>, <code>telemetry</code>, <code>rpc</code>, <code>build</code>); <code>go vet</code> nativo, <code>GOOS=windows</code> e <code>GOOS=js GOARCH=wasm</code>; <code>task lint-go GO_MODULES=apps/desktop</code> a 0 problemi; <code>go list -deps ./internal/app</code> senza <code>wailsapp</code>; generatore dei binding con <code>-check</code> pulito; vitest dello shim (33/33) e del mock; <code>task build-desktop</code> (<code>.app</code> universale x86_64+arm64, firma ad hoc valida, <code>Info.plist</code> reso, <code>minos 13.0</code>, circa 45 s); <code>task release-desktop OS=darwin</code> più <code>package-macos.sh</code> (<code>.dmg</code> con <code>MemoBrain Notes.app</code>); <code>task dev-desktop</code> (server esbuild su <code>127.0.0.1:5173</code>, riavvio dopo una modifica Go, ricarica dell&#39;interfaccia via SSE, SIGINT ferma app, esbuild e porta; sei avvii da <code>dist</code> assente senza errori; <code>version=dev</code> nel log); binario reale con data dir temporanea (finestra aperta e chiusa con SIGTERM, deep link a freddo e a caldo, seconda istanza che inoltra gli argomenti, nessun argomento di chiamata nel log); export HTML da 65, 200 e 250 MiB in un WKWebView reale; cross-build Windows (<code>memobrain.exe</code> con manifest e versione resi, installer NSIS, hash del bootstrapper contro il pin); <code>check-build-tags.sh</code> su binari reali e di prova (falliscono <code>production,mcp</code>, <code>production,devtools,gtk3</code>, <code>server</code>, <code>gtk3</code>).</p><p><strong>Non verificato:</strong> build Linux con <code>-tags gtk3</code>, controllo <code>ldd</code>, <code>.deb</code> e AppImage (<code>nfpm</code> e <code>appimagetool</code> assenti); esecuzione di exe e installer su Windows, «Annulla» nei cinque dialoghi, installazione e disinstallazione, firma; avvio dell&#39;app universale su un Mac Intel; <code>release.yml</code> su un runner vero; l&#39;installazione manuale sopra la 1.3.4 su ogni sistema operativo (§1.1 della matrice, il criterio di aggiornamento di M15) e, solo per build con chiave, l&#39;aggiornamento via updater su un canale di staging; Alt+F4, Quit dall&#39;updater, stampa, menu, fullscreen e <code>BrowserOpenURL</code> sui tre sistemi; il drop vero da Finder, Explorer e Nautilus; <code>location.reload()</code> nel binario reale; export HTML su WebView2 e WebKitGTK; la memoria di WebView2 con 250 MiB; single-instance su Ubuntu 22.04 e 24.04 con 50 data dir; i dialoghi agganciati alla finestra; <code>task ci</code>, <code>task lint</code> e <code>task parity</code> completi. La <strong>matrice manuale</strong> (<code>docs/qa/m15-wails3-matrice.md</code>) è da eseguire in B-W8 e l&#39;ADR resta in proposta fino ad allora; B-W9 (revisione di sicurezza, licenza del codice portato da v2, <code>rg wails/v2</code> vuoto) è da fare: oggi <code>deploy/PINS.md</code> e <code>apps/desktop/desktop</code> (un binario di 5 MB versionato, del 23 ottobre) contengono ancora la stringa <code>wails/v2</code>.</p><p>Lo spike B-W0 era un ramo non unito: l&#39;implementazione (B-W2…B-W7) è nel repository. L&#39;ADR resta in proposta fino alla decisione dell&#39;owner.</p><p><strong>Dopo B-W8 (parte automatica) e B-W9 (2026-11-11).</strong> L&#39;ADR resta in proposta. La <strong>matrice manuale non è stata eseguita</strong>: nessuna riga è spuntata e il registro di <code>docs/qa/m15-wails3-matrice.md</code> §4 è vuoto.</p><p><strong>Verificato (macOS arm64, Docker 29.9.3, Go 1.27.4):</strong></p><ul><li><code>task test-integration</code> verde (<code>test/integration</code>, 2 min 16 s) e <code>task test-desktop-e2e</code> verde (<code>internal/sync</code> e <code>internal/sync/transport</code>, 3 min 49 s); senza i conteggi dei singoli test Go, solo l&#39;esito per pacchetto.</li><li><code>task e2e</code>: 127 + 43 + 94 = 264 passati, 36 saltati (solo desktop-mock), 3 min 24 s.</li><li><code>task e2e-matrix</code>, primo giro: 245 passati, 4 falliti, 77 saltati (11 min 15 s). I quattro falli (<code>drawing-wp5.spec.ts:79</code> e <code>:93</code> su desktop-mock, <code>drawing-embed.spec.ts:105</code> e <code>:125</code> su web-core) sono tutti <code>browserContext.close: ENOENT</code> su un file di traccia sotto <code>.dev/e2e-matrix/5199-5176/test-results/</code>: la cartella dei risultati è sparita sotto Playwright mentre un altro <code>e2e:workbench-ui</code> girava sulla stessa macchina (ambiente, non regressione). Rilancio mirato con <code>--repeat-each=3</code>: 114 passati, 0 falliti, 6 saltati (8 min 24 s).</li><li><strong>Smoke del binario reale</strong> (macOS universale, <code>scripts/build-desktop-bin.sh --version 1.3.5-qa</code>, build di 17 s): avvio con data dir temporanea in 1,4 s; seconda istanza con la stessa data dir e <code>memobrain://open?…</code> inoltra l&#39;URL (URL oscurato nel log) ed esce con codice 0 in 0,6 s; con un&#39;altra data dir convive; SIGTERM chiude entrambi i processi in 0,15 s con «stopped» nel log e nessun residuo; <code>check-build-tags.sh</code> ok su x86_64 e arm64; <code>go version -m</code>: <code>-tags=production</code>, <code>-trimpath=true</code>, <code>CGO_ENABLED=1</code>, Go 1.27.4, nessuna traccia di <code>mcp</code>, <code>server</code>, <code>devtools</code>, porta 9099 non in ascolto; 129.624.928 byte contro 127.936.608 della 1.3.4 installata (+1,3%, entrambe universali).</li><li><strong>Revisione finale B-W9:</strong> identità dell&#39;installazione invariata (Bundle ID <code>dev.memobrain.desktop</code>, <code>CFBundleExecutable memobrain</code>, chiave Uninstall, <code>Software\\Classes\\memobrain</code>, <code>InstallDir</code>, <code>PRODUCT_EXECUTABLE</code>, <code>OutFile</code> fisso, bootstrapper in <code>tmp\\</code>); i dati di WebView2 usano lo stesso default di v2 (<code>%AppData%\\&lt;exe&gt;</code>, <code>internal/webview2/pkg/edge/chromium.go:241-250</code> di v3.1.0); data dir invariata (cambia solo <code>InstanceID</code>; su Linux <code>NON_UNIQUE</code> permette due istanze con data dir diverse); l&#39;unico uso di <code>localStorage</code> è <code>drawing/ToolsPanel.tsx</code>, quindi l&#39;azzeramento dichiarato su macOS e Linux è completo; <code>FRONTEND_DEVSERVER_URL</code> è ignorato nelle build <code>production</code>; <code>LICENSE-wails.txt</code> (MIT) e <code>LICENSE-typescriptify.txt</code> (Apache-2.0) presenti con la nota delle modifiche, <code>@wailsio/runtime</code> 3.1.0 MIT con pin esatto; nessun TODO o FIXME, nessun segreto, nessun test indebolito (cambia solo l&#39;elenco di <code>events_registry_test</code> per i file spostati; l&#39;unico <code>t.Skip</code> nuovo è con <code>-short</code>); lo stage 1 del Dockerfile genera i binding in <code>/src/packages/workbench/wailsjs</code>. Eseguiti: <code>go test -race -count=1</code> di <code>internal/shell</code>, <code>internal/platform</code>, <code>internal/telemetry</code>, <code>internal/rpc</code>, <code>build/</code> e del package principale; <code>go vet</code> con <code>GOOS=windows</code> e <code>GOOS=js GOARCH=wasm</code>; <code>go list -deps</code> senza <code>wailsapp</code> per <code>internal/app</code>, <code>cmd/memobrain-core</code> e il generatore; il generatore con <code>-check</code>; <code>go mod tidy -diff</code>; <code>install-wails.sh --check-pins</code> e <code>--check</code>; <code>bash -n</code> sugli 8 script.</li></ul><p><strong>Rilievi della revisione (verdetto Fail, per i primi due; chiusi dalle decisioni dell&#39;owner del 2026-11-11, vedi sotto):</strong></p><ol><li><strong>Media, processo: il rollback v3 → v2 puntava a un commit che non esiste. Chiuso dalla decisione dell&#39;owner (2026-11-11): nessun rollback a v2</strong>, i problemi gravi si correggono in avanti su v3 (vedi «Nessun rollback a v2»). Il fatto resta vero ma non serve più: <code>git log v1.3.4..HEAD</code> contiene solo <code>2451abb</code> e <code>bd9efc3</code>, perché B-W2…B-W9, la Parte A e Go 1.27.4 sono non committati. I commit sono richiesti a fine ondata, dopo <code>task ci</code> verde, su un ramo dedicato e non su <code>main</code>.</li><li><strong>Media, test-gap: la matrice provava solo l&#39;aggiornamento via updater, assente dalle build pubblicate. Chiuso dalla decisione dell&#39;owner (2026-11-11):</strong> <code>.github/workflows/release.yml:112</code> imposta <code>ALLOW_UNSIGNED_UPDATES: &#39;1&#39;</code> senza <code>UPDATE_PUBLIC_KEY</code> e <code>README.md:29-30</code> dice che le nuove versioni si installano a mano, quindi il criterio di M15 è l&#39;installazione manuale sopra la 1.3.4 su ogni sistema operativo (NSIS v3 sopra la 1.3.4 con la stessa <code>UNINST_KEY</code> e <code>InstallDir</code>; <code>.app</code> trascinata sulla vecchia; <code>apt install</code> del <code>.deb</code>). La voce è <code>docs/qa/m15-wails3-matrice.md</code> §1.1, <strong>da eseguire</strong> (nessuna riga spuntata); l&#39;aggiornamento via updater (§3) resta da provare solo per build con chiave.</li><li>Bassa: in §3.3 della matrice l&#39;installer Windows (<code>memobrain-amd64-installer.exe</code>, §0) non è rinominato, e <code>classify</code> (<code>tools/release/main.go:64-67</code>) scarta in silenzio i nomi con meno di 4 parti; il <code>cp</code> verso <code>memobrain-&lt;V&gt;-windows-&lt;arch&gt;.exe</code> esiste solo in <code>release.yml</code>. La matrice (§3.3) ora ha il passo di rinomina.</li><li>Bassa: la matrice (<code>:98</code>) dice che su macOS il trasporto è il «canale nativo dei messaggi»; B-W4b ha scelto l&#39;upload a blocchi sull&#39;asset server (vedi sopra); la frase della matrice è ora allineata.</li><li>Bassa: <code>scripts/build-desktop-bin.sh:121-128</code> lancia <code>yarn … run build</code> ereditando l&#39;ambiente: con <code>MEMOBRAIN_LIVE_ENGINE</code> (variabile rimossa in A-W9 di ADR-0049, dal 2026-11-12), <code>MEMOBRAIN_AI</code>, <code>MEMOBRAIN_COLLAB</code> o <code>MEMOBRAIN_E2E</code> esportate, <code>task release-desktop</code> produrrebbe un rilascio con Milkdown (allora dietro l&#39;interruttore) o con il mock dei binding; con <code>--release</code> lo script dovrebbe fallire se una di esse è impostata.</li><li>Bassa: riferimenti residui a v2 in <code>apps/desktop/internal/app/services_test.go:47</code> (<code>wails.json</code> <code>wailsjsdir</code>), <code>apps/desktop/cmd/memobrain-core/core_js.go:98</code> e <code>doc.go:40</code> e <code>web/src/workbench/bridge.ts:72</code> (OnDomReady di Wails), <code>deploy/PINS.md:46</code> (prescrive <code>go get …/wails/v2</code>: seguirlo reintroduce v2) e <code>docs/qa/m15-wails3-matrice.md:15</code> (rimandava ai log di uno scratchpad di sessione: corretto nella matrice; gli altri riferimenti sono della catena della build e non sono dichiarati chiusi qui).</li></ol><p><strong>Decisioni dell&#39;owner (2026-11-11) e stato.</strong> Nessun rollback a v2; criterio di aggiornamento di M15 = installazione manuale sopra la 1.3.4 (vedi sopra); Milkdown restava dietro l&#39;interruttore di build fino alle prove manuali dell&#39;owner (A-W9 in attesa); <strong>superato il 2026-11-12</strong>: l&#39;owner ha reso Milkdown l&#39;unico motore Live senza attendere le prove manuali, e l&#39;interruttore è rimosso (ADR-0049, «Esito di A-W9»). <code>.go-version</code> è ora <code>go1.27.4</code>, allineato a <code>apps/desktop/go.mod</code> e al resto del repository. L&#39;avviso per chi è su macOS 12 (serve macOS 13: <code>LSMinimumSystemVersion</code> <code>13.0.0</code> in <code>apps/desktop/build/darwin/Info.plist</code>) è nelle note di compatibilità del CHANGELOG, sezione <em>Unreleased</em>. <code>CLAUDE.md</code> è aggiornato nei fatti diventati falsi (Wails v3.1.0, <code>task dev-desktop</code> con <code>wails3 tool watcher</code>, binding da <code>internal/app/gen/bindings</code>); il vincolo «Wails v2» è segnalato come in revisione. <strong>Ancora da decidere, al momento dei commit:</strong> la rimozione del binario versionato <code>apps/desktop/desktop</code> (5 MB, M0), che blocca il criterio <code>rg wails/v2</code> vuoto: non è stato cancellato. <strong>Ancora da tenere d&#39;occhio:</strong> il filtro dei log (<code>UIRuntimeLogger</code>) dipende dal testo di Wails 3.1.0 e va ricontrollato a ogni aggiornamento.</p><p><strong>Non verificato.</strong> La matrice intera in un giro pulito a macchina libera; l&#39;apertura effettiva della nota da deep link (nello smoke non c&#39;era un vault; verificato solo l&#39;inoltro); la chiusura con nota sporca (SIGTERM provato senza note modificate); Windows, Linux (build con <code>gtk3</code>) e macOS Intel; finestra nativa, drop dei file, dialoghi; aggiornamento reale 1.3.4 → v3 → v2; <code>release.yml</code> su un runner; il <code>.dmg</code> della 1.3.5; vitest dello shim, <code>task ci</code>, <code>task parity</code>, <code>task docker-build</code> ed e2e non rieseguiti dalla revisione (ultimo esito verde: i rapporti delle onde).</p><p><strong>Accettazione (2026-11-20).</strong> L&#39;owner accetta l&#39;ADR (opzione A della proposta di spec v1.8) e lo spec v1.8 lo recepisce: Wails v3.1.0 in V-07, D-07, A-03, §1.3, §2.3.2, §2.5, §4.2, §4.5, C.2 e C.4. I punti aperti restano quelli dichiarati sopra: la matrice manuale B-W8 su Windows e Linux (<code>docs/qa/m15-wails3-matrice.md</code>) non è eseguita. Gli ADR e i file elencati in «Da aggiornare quando l&#39;ADR sarà accettato» sono allineati con note di emendamento, senza riscrivere il testo storico: ADR-0001, ADR-0005, ADR-0023, ADR-0025, ADR-0029, ADR-0030 e ADR-0031; per ADR-0045, ADR-0048, <code>CONTRIBUTING.md</code>, <code>docs/release/README.md</code> e <code>docs/desktop-web-sync.md</code> non c&#39;era nulla di falso da correggere (<code>CLAUDE.md</code>, che l&#39;ADR elenca, lo aggiorna l&#39;owner).</p>',74)])])}const m=o(c,[["render",t]]);export{g as __pageData,m as default};
